pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {NewIntelTechMedia} from "../src/NewIntelTechMedia.sol";

contract InvMutTest is Test {
    NewIntelTechMedia c;
    function setUp() public { c = new NewIntelTechMedia(); }
    function testRegression_property() public {
        address owner = address(this);
        c.NETM();

        address spender = address(0x1234);
        bool firstApprove = c.approve(spender, 5);

        bool secondApprove = c.approve(spender, 10);

        assertTrue(secondApprove == false, "Reference rejects non-zero allowance change");
    }
}
